/* Global Styles for Print */
@media print {
    /* Ensures page breaks happen at specified locations */
    .page-break-before {
        page-break-before: always;
    }

    /* Adjust the body layout for printing */
    body {
        margin: 0;
        counter-reset: page;
    }

    /* Hide buttons during print */
    button {
        display: none;
    }

    /* Page size and margins */
    @page {
        size: A4 portrait;
        margin: 10mm;
    }

    /* Page number formatting */
    .page-no::after {
        counter-increment: page;
        content: "Page " counter(page);
    }

    /* Header and Footer Styles */
    .page-header, .page-footer {
        position: fixed;
        width: 100%;
        margin: auto;
    }

    .page-header {
        top: 0;
        height: 50px; /* Adjust as needed */
        border-bottom: 0 !important;
        display: block;
        color: #ffffff;
        padding-left: 0 !important;
    }

    .page-footer {
        bottom: 0;
        height: 50px; /* Adjust as needed */
        display: block;
    }

    .page-header-space, .page-footer-space {
        height: 50px; /* Adjust space if necessary */
    }

    /* Table headers and footers */
    thead {
        display: table-header-group;
    }

    tfoot {
        display: table-footer-group;
    }

    /* Formatting for page breaks and section headers */
    .print-format .print-format-preview {
        padding-left: 0px !important;
        padding-top: 0px !important;
    }

    /* Page break and spacing for scoped content */
    .scope-work {
        margin-inline: 60px;
        margin-bottom: 30px;
    }

    /* Scoped table style */
    .scope-work-table {
        border: 1px solid black;
        color: black !important;
        width: 100%;
        border-collapse: collapse;
    }

    .scope-work-table th {
        background-color: #c9daf8;
        color: black !important;
        text-align: center;
        font-weight: bold !important;
    }

    .scope-work-table th:nth-child(1),
    .scope-work-table th:nth-child(2) {
        width: 20%;
        min-width: 150px;
    }

    .scope-work-table th:nth-child(3) {
        width: 60%;
    }

    /* Table for tests */
    .test-table {
        color: black !important;
        width: 100%;
        border-collapse: collapse;
    }

    .test-table td {
        text-align: left;
        border-bottom: 1px solid black;
        border-left: 1px solid black;
        border-right: 1px solid black;
    }

    .test-table td:nth-child(1),
    .test-table td:nth-child(2) {
        width: 20%;
        min-width: 150px;
    }

    .test-table td:nth-child(3) {
        width: 60%;
    }

    /* Custom Heading Styles */
    .print-heading {
        display: none;
    }

    .text-center h4 {
        display: none;
    }

    /* Page header margin for print */
    .page-header {
        margin-top: 0px !important;
    }
    
    /*.page {*/
    /*        page-break-after: always;*/
    /*    }*/
    .ql-editor.read-mode p span {
    background-color: transparent !important; /* Remove background color */
    font-size: 14px;
    color: rgb(248, 248, 248);
}
}

